<?php
require 'config.php';require 'includes/functions.php';require_login();verify_csrf();$uid=current_user_id();$month=$_GET['month']??date('Y-m');
if($_SERVER['REQUEST_METHOD']==='POST'){$cat=(int)$_POST['category_id'];$m=$_POST['budget_month'];$amount=(float)$_POST['amount'];$s=$pdo->prepare("SELECT id FROM categories WHERE id=? AND type='expense' AND (user_id IS NULL OR user_id=?)");$s->execute([$cat,$uid]);if(!$s->fetch()||$amount<=0||!preg_match('/^\d{4}-\d{2}$/',$m)){set_flash('Dữ liệu ngân sách không hợp lệ.','error');}else{$s=$pdo->prepare("INSERT INTO budgets(user_id,category_id,budget_month,amount) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount)");$s->execute([$uid,$cat,$m,$amount]);set_flash('Đã lưu ngân sách.');}redirect('budgets.php?month='.urlencode($m));}
if(isset($_GET['delete'])){$s=$pdo->prepare("DELETE FROM budgets WHERE id=? AND user_id=?");$s->execute([(int)$_GET['delete'],$uid]);set_flash('Đã xóa ngân sách.');redirect('budgets.php?month='.urlencode($month));}
$c=$pdo->prepare("SELECT * FROM categories WHERE type='expense' AND (user_id IS NULL OR user_id=?) ORDER BY name");$c->execute([$uid]);$cats=$c->fetchAll();
$s=$pdo->prepare("SELECT b.*,c.name,COALESCE(SUM(t.amount),0) spent FROM budgets b JOIN categories c ON c.id=b.category_id LEFT JOIN transactions t ON t.user_id=b.user_id AND t.category_id=b.category_id AND t.type='expense' AND DATE_FORMAT(t.transaction_date,'%Y-%m')=b.budget_month WHERE b.user_id=? AND b.budget_month=? GROUP BY b.id ORDER BY c.name");$s->execute([$uid,$month]);$rows=$s->fetchAll();
$pageTitle='Ngân sách tháng';require 'includes/header.php';?>
<div class="grid two-col"><section class="card form-card"><div class="section-head"><h2>Thiết lập ngân sách</h2></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Danh mục chi tiêu</label><select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field" style="margin-top:14px"><label>Tháng áp dụng</label><input type="month" name="budget_month" value="<?=e($month)?>" required></div><div class="field" style="margin-top:14px"><label>Số tiền ngân sách (VNĐ)</label><input type="number" name="amount" min="1" required placeholder="Ví dụ: 2000000"></div><div class="form-actions"><button class="btn">Lưu ngân sách</button></div></form><p class="stat-note">Nếu đã có ngân sách cho danh mục trong tháng, số tiền mới sẽ thay thế số cũ.</p></section>
<section class="card"><div class="section-head"><h2>Tình hình sử dụng</h2></div><form class="filter"><div class="field"><label>Chọn tháng</label><input type="month" name="month" value="<?=e($month)?>"></div><button class="btn">Xem</button></form>
<?php if(!$rows):?><div class="empty">Chưa thiết lập ngân sách cho tháng này.</div><?php else:foreach($rows as $r):$pct=$r['amount']>0?$r['spent']/$r['amount']*100:0;?><div class="budget-row"><div class="budget-meta"><div class="category-name"><span class="category-icon expense"><?=e(category_icon($r['name'], 'expense'))?></span><strong><?=e($r['name'])?></strong></div><span class="<?=$pct>100?'red':''?>"><?=number_format($pct,1)?>%</span></div><div class="progress <?=$pct>100?'over':''?>"><span style="width:<?=min(100,$pct)?>%"></span></div><div class="budget-meta"><span class="muted">Đã chi: <?=money($r['spent'])?></span><strong><?=money($r['amount'])?></strong></div><?php if($pct>100):?><p class="red" style="font-size:11px">Cảnh báo: khoản chi đã vượt ngân sách <?=money($r['spent']-$r['amount'])?>.</p><?php endif;?><div style="text-align:right"><a class="btn btn-danger btn-small" href="?month=<?=e($month)?>&delete=<?=$r['id']?>" data-confirm="Xóa ngân sách này?">Xóa</a></div></div><?php endforeach;endif;?></section></div>
<?php require 'includes/footer.php';?>
